contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depAmt, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmt)); require(depAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depAmt, "not enough ether");

        c.Deposit{value: depAmt}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted || balAfter <= balBefore);
    }

    receive() external payable {}
}

